-- Uploaded lessons are generated by process-upload, not by the legacy course
-- importer. The pre-existing `lessons` table still carried that importer's
-- NOT NULL columns (course_id, material_id, ord, generator, payload) and had
-- no default for created_at, so every lesson insert from the Edge Function
-- failed with:
--
--   null value in column "course_id" of relation "lessons"
--
-- Relax only those legacy constraints. Existing course rows, foreign keys and
-- data are untouched; a generated lesson simply has no legacy course link.
-- Run once against the project database, then redeploy nothing (the function
-- insert becomes valid as-is).

do $$
declare
  legacy_column text;
begin
  foreach legacy_column in array array['course_id', 'material_id', 'ord', 'generator', 'payload'] loop
    if exists (
      select 1 from information_schema.columns
      where table_schema = 'public' and table_name = 'lessons' and column_name = legacy_column
    ) then
      execute format('alter table public.lessons alter column %I drop not null', legacy_column);
    end if;
  end loop;
end $$;

alter table public.lessons alter column created_at set default now();
